structureCode.vanilla:
const calendario = createCalendar({
  mode: 'single',                        // single | multiple | range
  value: new Date(2026, 3, 12),          // Date | Date[] | { from, to }
  onSelect: (valor) => console.log(valor),
  locale: 'pt-BR',                       // Intl.DateTimeFormat
  captionLayout: 'label',                // label (texto) | dropdown (seletores)
  numberOfMonths: 1,
});

customizationCode.web:
/* Células maiores para telas touch, sem tocar na escala global. */
.agenda-touch .nds-calendar-root {
  --nds-cell-size: 2.5rem;
  --nds-cell-radius: var(--radius-sm);
}

